import java.util.*; public class Solution { public List<Integer> findSubstring(String s, String[] words) { List<Integer> result = new ArrayList<>(); if (s == null || words == null || words.length == 0) return result; int wordLen = words[0].length(); int wordCount = words.length; int totalLen = wordLen * wordCount; if (s.length() < totalLen) return result; Map<String, Integer> wordFreq = new HashMap<>(); for (String w : words) wordFreq.put(w, wordFreq.getOrDefault(w, 0) + 1); for (int i = 0; i < wordLen; i++) { int left = i; int count = 0; Map<String, Integer> windowFreq = new HashMap<>(); for (int right = i; right <= s.length() - wordLen; right += wordLen) { String word = s.substring(right, right + wordLen); if (wordFreq.containsKey(word)) { windowFreq.put(word, windowFreq.getOrDefault(word, 0) + 1); count++; while (windowFreq.get(word) > wordFreq.get(word)) { String leftWord = s.substring(left, left + wordLen); windowFreq.put(leftWord, windowFreq.get(leftWord) - 1); count--; left += wordLen; } if (count == wordCount) { result.add(left); String leftWord = s.substring(left, left + wordLen); windowFreq.put(leftWord, windowFreq.get(leftWord) - 1); count--; left += wordLen; } } else { windowFreq.clear(); count = 0; left = right + wordLen; } } } return result; } }